SUITES = (suite15.CoberturaBrvtal15Tests,
          suite16.CoberturaBrvtal16Tests,
          suite19.CoberturaBrvtal19Tests,
          suite20.CoberturaBrvtal20Tests,
          suite21.CoberturaBrvtal21Tests)
PROBES = {
    f"tests/{cls.__module__}.py::{cls.__qualname__}.{method}"
    for cls in SUITES
    for method in unittest.defaultTestLoader.getTestCaseNames(cls)
}


def classification(identifier: str) -> tuple[str, int]:
    """Use independent executable contract inventories, never matrix labels."""
    if identifier in suite15.PROVEN:
        return "A", 15
    if identifier in suite15.NEEDS_REAL:
        return "B", 15
    if identifier in suite15.DOCUMENTAL:
        return "C", 15
    if identifier in suite16.GRID_IDS:
        return "A", 16
    if identifier in suite19.OFFLINE:
        return "A", 19
    if identifier in suite19.EXTERNAL:
        return "B", 19
    if identifier in suite19.DECLARATIVE:
        return "C", 19
    if identifier in suite20.B:
        return "B", 20
    if identifier in suite20.C:
        return "C", 20
    if identifier in suite21.A:
        return "A", 21
    if identifier in suite21.B:
        return "B", 21
    if identifier in suite21.C:
        return "C", 21
    raise AssertionError("No independently tracked witness: " + identifier)


def rows(report: str) -> dict[str, list[str]]:
    section = report.split("## Registro de las 50 filas\n", 1)[1].split("\n## ", 1)[0]
    found = {}
    for line in section.splitlines():
        if not line.startswith("| S"):
            continue
        cells = [cell.strip() for cell in line.strip().strip("|").split("|")]
        if len(cells) != 8 or cells[0] in found:
            raise AssertionError("Duplicated or malformed coverage record: " + line[:110])
        found[cells[0]] = cells
    return found


def verify_report(report: str) -> None:
    actual = rows(report)
    expected = {case["id"] for case in CASES}
    if set(actual) != expected or len(actual) != 50:
        raise AssertionError("Coverage batch must contain exactly the 50 claimed IDs")
    for case in CASES:
        identifier = case["id"]
        required = [
            identifier, "NO_VERIFICABLE", case["kind"], case["req"],
            chr(96) + case["source"] + chr(96),
            chr(96) + case["probe"] + chr(96),
            f"[#{case['prior_pr']}](https://github.com/pl0n3r/brvtal/pull/{case['prior_pr']})",
            case["gap"],
        ]
        if actual[identifier] != required:
            raise AssertionError("Evidence drift or unproved coverage promotion: " + identifier)


def canonical(value: str) -> str:
    """Normalize only Markdown inline markup, placeholders and whitespace."""
    value = re.sub(r"<[^>]*>", "", value)
    return re.sub(r"\s+", " ", value.replace("*", "").replace(chr(96), "")).strip()


class VerificacionBrvtal07Tests(unittest.TestCase):
    def test_registro_exactamente_50_filas(self) -> None:
        self.assertEqual(len(CASES), 50)
        self.assertEqual(len({c["id"] for c in CASES}), 50)
        self.assertEqual(
            {kind: sum(c["kind"] == kind for c in CASES)
             for kind in ("A", "B", "C")}, {"A": 9, "B": 18, "C": 23})
        report = REPORT.read_text(encoding="utf-8")
        verify_report(report)
        self.assertIn("0 promociones a CUBIERTO", report)
        self.assertNotIn("| CUBIERTO |", report)

    def test_matriz_spec_y_testigos_independientes(self) -> None:
        """Detect requirement drift, fake tests, invented PRs or false upgrades."""
        matrix = MATRIX.read_text(encoding="utf-8")
        spec = canonical(SPEC.read_text(encoding="utf-8"))
        for case in CASES:
            identifier = case["id"]
            with self.subTest(id=identifier):
                self.assertEqual(classification(identifier),
                                 (case["kind"], case["group"]))
                self.assertIn(case["probe"], PROBES)
                self.assertTrue((ROOT / case["source"]).is_file())
                self.assertGreater(len(case["gap"]), 35)
                self.assertIn(canonical(case["req"]), spec)
                matching = [line for line in matrix.splitlines()
                            if line.startswith("| " + identifier + " ·")]
                self.assertEqual(len(matching), 1)
                columns = [cell.strip() for cell in matching[0].strip("|").split("|")]
                self.assertEqual(len(columns), 5)
                self.assertEqual(columns[1:3], [case["req"], "NO_VERIFICABLE"])
                self.assertEqual(columns[3], case["kind"] + " · " + case["gap"])
                self.assertIn("PR #" + str(case["prior_pr"]), columns[4])

    def test_regresion_ejecutable_y_negativos(self) -> None:
        """Run real versioned PHP/JS-backed tests, including negative boundaries."""
        suite = unittest.TestSuite()
        for cls in SUITES:
            suite.addTests(unittest.defaultTestLoader.loadTestsFromTestCase(cls))
        output = io.StringIO()
        result = unittest.TextTestRunner(stream=output, verbosity=0).run(suite)
        self.assertEqual(result.testsRun, 17)
        self.assertTrue(result.wasSuccessful(),
                        "Inherited real test regression: " + output.getvalue()[-2500:])

    def test_detecta_omisiones_duplicados_y_promocion_falsa(self) -> None:
        content = REPORT.read_text(encoding="utf-8")
        first = CASES[0]["id"]
        original = rows(content)
        line = next(line for line in content.splitlines()
                    if line.startswith("| " + first + " |"))
        with self.assertRaises(AssertionError):
            verify_report(content.replace(line + "\n", "", 1))
        with self.assertRaises(AssertionError):
            rows(content.replace(line, line + "\n" + line, 1))
        with self.assertRaises(AssertionError):
            verify_report(content.replace(
                "| " + first + " | NO_VERIFICABLE |",
                "| " + first + " | CUBIERTO |", 1))
        with self.assertRaises(AssertionError):
            verify_report(content.replace(
                "| " + first + " | NO_VERIFICABLE | C |",
                "| " + first + " | NO_VERIFICABLE | B |", 1))
        self.assertEqual(len(original), 50)

    def test_fixtures_sinteticos_y_limites_reales(self) -> None:
        """No direct network, DB, browser, Hostinger or production fixture."""
        source = Path(__file__).read_text(encoding="utf-8")
        forbidden = {"requests", "httpx", "urllib", "socket", "mysql",
                     "pymysql", "psycopg2", "selenium", "playwright"}
        for node in ast.walk(ast.parse(source)):
            if isinstance(node, ast.Import):
                self.assertFalse({n.name.split(".")[0] for n in node.names} & forbidden)
            elif isinstance(node, ast.ImportFrom) and node.module:
                self.assertNotIn(node.module.split(".")[0], forbidden)
        for case in CASES:
            self.assertFalse(Path(case["source"]).is_absolute())
            self.assertNotIn("..", Path(case["source"]).parts)
        report = REPORT.read_text(encoding="utf-8")
        self.assertIn("NO_VERIFICABLE", report)
        self.assertIn("no toca credenciales", report.lower())


if __name__ == "__main__":
    unittest.main()
